L["the last few things that broke"] = "последние несколько ошибок"
L["tools for testing the addon on this client: the click log, try, look and forms"] = "инструменты для проверки аддона в этом клиенте: журнал щелчков, try, look и forms"
L["log what the button does when clicked"] = "записывать, что делает кнопка при щелчке"
L["run any macro text from the prompt"] = "выполнить любой текст макроса с панели"
L["dump every API answer for a unit"] = "вывести все ответы API для юнита"
L["example macros to try"] = "примеры макросов для проверки"
L["Manners commands:"] = "Команды Manners:"
L["|cffffd100/mnr|r works in place of |cffffd100/manners|r in all of them."] = "Во всех командах вместо |cffffd100/manners|r можно писать |cffffd100/mnr|r."
L["try cleared -- the normal cast takes effect when this fight ends; until then a press runs the macro already on the button."] = "тестовый макрос сброшен -- обычное применение вернется, когда бой закончится; до тех пор нажатие выполняет макрос, уже назначенный кнопке."
L["try cleared -- back to the normal cast."] = "тестовый макрос сброшен -- снова обычное применение."
L["try armed: |cff80ff80%s|r"] = "тестовый макрос заряжен: |cff80ff80%s|r"
L["|cffff8080not armed for now:|r %s."] = "|cffff8080пока не заряжено:|r %s."
L["expands to: |cffffffff%s|r"] = "после подстановки: |cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "Символов: %d -- на %d больше, чем вмещает макрос (%d). Клиент обрежет его, и выполнится не то, что выведено выше."
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "Он вступит в силу, когда бой закончится; до тех пор нажатие выполняет макрос, уже назначенный кнопке. |cffffd100/manners try|r без текста сбрасывает его."
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "Панель зарядит его, как только у игрока появится токен юнита. |cffffd100/manners try|r без текста сбрасывает его."
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "Щелкните по панели, чтобы выполнить его. |cffffd100/manners try|r без текста сбрасывает его."
L["Targeting forms, for /manners try:"] = "Варианты выбора цели для /manners try:"
L["(on yourself)"] = "(на себя)"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "Токены: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} -- имя, под которым записан долг, {aim} -- то, что нужно строке выбора цели. Для новой строки используйте \\n."
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "журнал любезностей не загрузился -- переустановите Manners, это должно помочь."
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "панель откреплена -- ее можно будет перетащить, когда бой закончится; до тех пор нажатие применяет то, что заморозил бой. Затем введите |cffffd100/manners lock|r."
L["unlocked -- it can be dragged once this fight ends; nothing is armed meanwhile. Then |cffffd100/manners lock|r."] = "панель откреплена -- ее можно будет перетащить, когда бой закончится; а пока ничего не заряжено. Затем введите |cffffd100/manners lock|r."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "панель откреплена -- перетащите ее, затем введите |cffffd100/manners lock|r."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "панель откреплена, но аддон |cffff8080выключен|r, поэтому перетаскивать нечего -- сначала введите |cffffd100/manners on|r."
L["locked."] = "панель закреплена."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "возврат прежней цели после баффа: |cff00ff00вкл.|r -- вступит в силу, когда бой закончится; до тех пор нажатие выполняет макрос, уже назначенный кнопке."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "возврат прежней цели после баффа: |cffff0000выкл.|r -- вступит в силу, когда бой закончится; до тех пор нажатие выполняет макрос, уже назначенный кнопке."
L["hand your target back after buffing: |cff00ff00on|r"] = "возврат прежней цели после баффа: |cff00ff00вкл.|r"
L["hand your target back after buffing: |cffff0000off|r"] = "возврат прежней цели после баффа: |cffff0000выкл.|r"
L["click logging: |cff00ff00on|r"] = "журнал щелчков: |cff00ff00вкл.|r"
L["click logging: |cffff0000off|r"] = "журнал щелчков: |cffff0000выкл.|r"
